import { createAsyncThunk, createSlice } from "@reduxjs/toolkit";
import { api } from "../config/Api";
import { User } from "../types/userTypes";

export const sendLoginSignupOtp = createAsyncThunk("/auth/sendLoginSignupOtp",
    async ({ email, }: { email: string, }, { rejectWithValue }) => {
        try {
            const response = await api.post("/auth/sent/login-signup-otp", {
                email,

            })
            console.log("login/ signup otp", response.data)
            return response.data
        } catch (error: any) {
            console.log("error...", error)
            return rejectWithValue(error.response?.data?.message || "failed to send OTP")
        }
    }
)

export const signin = createAsyncThunk<any, any>(
    "/auth/signing",
    async (loginRequest, { rejectWithValue }) => {
        try {
            // const email = loginRequest.isSeller
            //     ? `seller_${loginRequest.email}`
            //     : loginRequest.email;

            const response = await api.post("/auth/signing", {

                email: loginRequest.email,
                otp: loginRequest.otp,
                role: loginRequest.role
            });

            console.log("login otp", response.data);
            localStorage.setItem("jwt", response.data.jwt);
            return response.data.jwt;
        } catch (error: any) {
            console.log("error...", error);
            return rejectWithValue(error.response?.data?.message || "Login failed");
        }
    }
);


export const signup = createAsyncThunk<any, any>("/auth/signup",
    async (signupRequest, { rejectWithValue }) => {
        try {
            const response = await api.post("/auth/signup", signupRequest)
            console.log("login otp", response.data)
            localStorage.setItem("jwt", response.data.jwt)
            return response.data.jwt;
        } catch (error: any) {
            console.log("error...", error)
            return rejectWithValue(error.response?.data?.message || "Signup failed")
        }
    }
)

export const fetchUserProfile = createAsyncThunk<any, any>("/auth/fetchUserProfile",
    async ({ jwt }, { rejectWithValue }) => {
        try {
            const response = await api.get("/users/profile", {
                headers: {
                    Authorization: `Bearer ${jwt}`
                }
            })
            console.log("user profile", response.data)
            return response.data;
        } catch (error) {
            console.log("error...", error)
        }
    }
)

export const logout = createAsyncThunk<any, any>("/auth/logout",
    async (navigate, { rejectWithValue }) => {
        try {
            localStorage.clear()
            console.log("logged out successfully..")
            navigate("/")
        } catch (error) {
            console.log("error...", error)
        }
    }
)

interface AuthState {
    jwt: string | null,
    otpSent: boolean,
    isLoggedIn: boolean,
    user: User | null,
    loading: boolean,
    error: string | null,
    token: string | null
}

const initialState: AuthState = {
    jwt: null,
    otpSent: false,
    isLoggedIn: false,
    user: null,
    loading: false,
    error: null,
    token: null,
}

const authSlice = createSlice({
    name: "auth",
    initialState,
    reducers: {},
    extraReducers: (builder) => {

        builder.addCase(sendLoginSignupOtp.pending, (state) => {
            state.loading = true;
        })
        builder.addCase(sendLoginSignupOtp.fulfilled, (state) => {
            state.loading = false;
            state.otpSent = true;
        })
        builder.addCase(sendLoginSignupOtp.rejected, (state, action) => {
            state.loading = false;
            state.error = action.payload as string
        })

        builder.addCase(signin.fulfilled, (state, action) => {
            state.jwt = action.payload
            state.isLoggedIn = true
            state.token = action.payload
        })
        builder.addCase(signup.fulfilled, (state, action) => {
            state.jwt = action.payload
            state.isLoggedIn = true
        })
        builder.addCase(fetchUserProfile.fulfilled, (state, action) => {
            state.user = action.payload
            state.isLoggedIn = true
        })
        builder.addCase(logout.fulfilled, (state) => {
            state.jwt = null
            state.isLoggedIn = false
            state.user = null
        })
    }
})

export default authSlice.reducer;

import { createAsyncThunk, createSlice } from "@reduxjs/toolkit";
import { api } from "../../config/Api";
import { Product } from "../../types/productType";


export const fetchSellerProducts = createAsyncThunk<Product[], any>(
    "/sellerProduct/fetchSellerProducts",
    async (jwt, { rejectWithValue }) => {
        try {
            const response = await api.get("/sellers/products", {
                headers: {
                    Authorization: `Bearer ${jwt}`,
                },
            })
            const data = response.data;

            console.log("seller products", data)
            return data;
        } catch (error) {
            console.log("error...", error);
            throw error;

        }
    }
)

export const createProduct = createAsyncThunk<Product, { request: any, jwt: string | null }>(
    "sellers/createProduct",
    async (Args, { rejectWithValue }) => {
        const { request, jwt } = Args;
        try {
            const response = await api.post("/sellers/products", request, {
                headers: {
                    Authorization: `Bearer ${jwt}`,
                },
            })
            console.log("product created", response.data)
            return response.data;

        } catch (error) {
            console.log("Error...", error);
            // throw error;
        }
    }
)

interface SellerProductState {
    products: Product[];
    loading: boolean;
    error: string | null | undefined;
}

const initialState: SellerProductState = {
    products: [],
    loading: false,
    error: null,
}

const sellerProductSlice = createSlice({
    name: "sellerProduct",
    initialState,
    reducers: {},
    extraReducers: (builder) => {
        builder.addCase(fetchSellerProducts.pending, (state) => {
            state.loading = true;
        })
        builder.addCase(fetchSellerProducts.fulfilled, (state, action) => {
            state.loading = false;
            state.products = action.payload;
        })
        builder.addCase(fetchSellerProducts.rejected, (state, action) => {
            state.loading = false;
            state.error = action.error.message;
        })

        builder.addCase(createProduct.pending, (state) => {
            state.loading = true;
        })
        builder.addCase(createProduct.fulfilled, (state, action) => {
            state.loading = false;
            state.products.push(action.payload);
        })
        builder.addCase(createProduct.rejected, (state, action) => {
            state.loading = false;
            state.error = action.error.message;
        })

    }
})

export default sellerProductSlice.reducer;

import { Delete } from '@mui/icons-material';
import { Button, Paper, styled, Table, TableBody, TableCell, tableCellClasses, TableContainer, TableHead, TableRow } from '@mui/material'
import { useState } from 'react'

const accountStatuses = [
    { status: 'PENDING_VERIFICATION', title: 'Active', description: 'Account is pending verifivation' },
    { status: 'ACTIVE', title: 'Pending Verification', description: 'Account is active and in good condition' },
    { status: 'SUSPENDED', title: 'Suspended', description: 'Account is Temporarily Suspended' },
    { status: 'DEACTIVATED', title: 'Deactivated', description: 'Account isdeactivated' },
    { status: 'BANNED', title: 'Banned', description: 'Account is Permanently banned due to violation' },
    { status: 'CLOSED', title: 'Closed', description: 'Account is permanently closed by owner' },
];
const StyledTableCell = styled(TableCell)(({ theme }) => ({
    [`&.${tableCellClasses.head}`]: {
        backgroundColor: theme.palette.common.black,
        color: theme.palette.common.white,
    },
    [`&.${tableCellClasses.body}`]: {
        fontSize: 14,
    },
}));

const StyledTableRow = styled(TableRow)(({ theme }) => ({
    '&:nth-of-type(odd)': {
        backgroundColor: theme.palette.action.hover,
    },
    // hide last border
    '&:last-child td, &:last-child th': {
        border: 0,
    },
}));

function createData(
    name: string,
    calories: number,
    fat: number,
    carbs: number,
    protein: number,
) {
    return { name, calories, fat, carbs, protein };
}

const rows = [
    createData('Frozen yoghurt', 159, 6.0, 24, 4.0),
    createData('Ice cream sandwich', 237, 9.0, 37, 4.3),
    createData('Eclair', 262, 16.0, 24, 6.0),
    createData('Cupcake', 305, 3.7, 67, 4.3),
    createData('Gingerbread', 356, 16.0, 49, 3.9),
];

const Coupon = () => {
    const [accountStatus, setAccountStatus] = useState("ACTIVE")

    const handleChange = (event: any) => {
        setAccountStatus(event.target.value)
    }
    return (
        <>

            <TableContainer component={Paper}>
                <Table sx={{ minWidth: 700 }} aria-label="customized table">
                    <TableHead>
                        <TableRow>
                            <StyledTableCell>Coupon Code</StyledTableCell>
                            <StyledTableCell>Start Date</StyledTableCell>
                            <StyledTableCell>End Date</StyledTableCell>
                            <StyledTableCell align="right">Minimum Order Value</StyledTableCell>
                            <StyledTableCell align="right">Discount</StyledTableCell>
                            <StyledTableCell align="right">Status</StyledTableCell>
                            <StyledTableCell align="right">Delete</StyledTableCell>
                        </TableRow>
                    </TableHead>
                    <TableBody>
                        {rows.map((row) => (
                            <StyledTableRow key={row.name}>
                                <StyledTableCell component="th" scope="row">
                                    {row.name}
                                </StyledTableCell>
                                <StyledTableCell >{row.calories}</StyledTableCell>
                                <StyledTableCell align="right">{row.fat}</StyledTableCell>
                                <StyledTableCell align="right">{row.fat}</StyledTableCell>
                                <StyledTableCell align="right">{row.carbs}</StyledTableCell>
                                <StyledTableCell align="right">{row.carbs}</StyledTableCell>
                                <StyledTableCell align="right">
                                    <Button><Delete /></Button>
                                </StyledTableCell>
                            </StyledTableRow>
                        ))}
                    </TableBody>
                </Table>
            </TableContainer>
        </>
    )
}

export default Coupon

