import { useState, useEffect } from 'react';
import { useAppDispatch, useAppSelector } from '../../../State/store';
import { useFormik } from 'formik';
import { Button, CircularProgress, TextField, InputAdornment } from '@mui/material';
import { getRoleFromToken } from '../../../Util/jwtHelpers';
import { fetchUserProfile, sendLoginSignupOtp, signin } from '../../../State/authSlice';
import { useNavigate } from 'react-router-dom';
import * as Yup from 'yup';
import { toast } from 'react-toastify';
import { motion, AnimatePresence } from 'framer-motion';
import { CheckCircle } from 'lucide-react';
import ResendOtpButton from '../../../component/common/ResendOtpButton';

const emailSchema = Yup.object({
    email: Yup.string().email('Invalid email format').required('Email is required'),
});

const loginSchema = Yup.object({
    email: Yup.string().email('Invalid email format').required('Email is required'),
    otp: Yup.string().required('OTP is required'),
});

const LoginForm = () => {
    const navigate = useNavigate();
    const dispatch = useAppDispatch();
    const { auth } = useAppSelector((store) => store);

    const [isOtpSent, setIsOtpSent] = useState(false);
    const [resendTimer, setResendTimer] = useState(0);

    const formik = useFormik({
        initialValues: {
            email: '',
            otp: '',
        },
        validationSchema: isOtpSent ? loginSchema : emailSchema,
        onSubmit: async (values) => {
            try {
                const result = await dispatch(signin({ ...values, role: 'CUSTOMER' })).unwrap();
                toast.success('Logged in successfully!');
            } catch (error: any) {
                console.error('Login failed:', error);
                toast.error(error?.message || 'Login failed.');
            }
        },
    });

    const handleSendOtp = async () => {
        try {
            await emailSchema.validate({ email: formik.values.email });
            await dispatch(sendLoginSignupOtp({ email: formik.values.email })).unwrap();
            toast.success('OTP sent to your email!');
            setIsOtpSent(true);
            setResendTimer(60);
        } catch (error: any) {
            if (error.name === 'ValidationError') {
                formik.setFieldError('email', error.message);
            } else {
                toast.error(error?.message || 'Failed to send OTP.');
            }
        }
    };

    useEffect(() => {
        let timer: NodeJS.Timeout;
        if (resendTimer > 0) {
            timer = setTimeout(() => setResendTimer((prev) => prev - 1), 1000);
        }
        return () => clearTimeout(timer);
    }, [resendTimer]);

    useEffect(() => {
        if (auth.jwt) {
            const role = getRoleFromToken(auth.jwt);
            if (role === 'CUSTOMER') {
                dispatch(fetchUserProfile(auth.jwt));
                navigate('/account');
            } else {
                navigate('/');
            }
        }
    }, [auth.jwt, dispatch, navigate]);

    return (
        <div className="max-w-sm mx-auto p-6 space-y-6 border rounded shadow">
            <h1 className="text-center font-bold text-2xl text-primary-color pb-4">User Login</h1>

            <form onSubmit={formik.handleSubmit} className="space-y-5">
                <TextField
                    fullWidth
                    name="email"
                    label="Email"
                    value={formik.values.email}
                    onChange={formik.handleChange}
                    onBlur={formik.handleBlur}
                    error={formik.touched.email && Boolean(formik.errors.email)}
                    helperText={formik.touched.email && formik.errors.email}
                    InputProps={{
                        endAdornment: (
                            <InputAdornment position="end">
                                <AnimatePresence>
                                    {isOtpSent && (
                                        <motion.div
                                            key="success-icon"
                                            initial={{ scale: 0, opacity: 0 }}
                                            animate={{ scale: 1, opacity: 1 }}
                                            exit={{ scale: 0, opacity: 0 }}
                                            transition={{ type: 'spring', stiffness: 300, damping: 15 }}
                                        >
                                            <CheckCircle className="text-green-500" size={22} />
                                        </motion.div>
                                    )}
                                </AnimatePresence>
                            </InputAdornment>
                        ),
                    }}
                />

                <AnimatePresence>
                    {isOtpSent && (
                        <motion.div
                            key="otp-field"
                            initial={{ opacity: 0, y: -10 }}
                            animate={{ opacity: 1, y: 0 }}
                            exit={{ opacity: 0, y: -10 }}
                            transition={{ duration: 0.3 }}
                            className="space-y-2"
                        >
                            <p className="font-medium text-sm opacity-60">Enter OTP sent to your email</p>
                            <TextField
                                fullWidth
                                name="otp"
                                label="OTP"
                                value={formik.values.otp}
                                onChange={formik.handleChange}
                                onBlur={formik.handleBlur}
                                error={formik.touched.otp && Boolean(formik.errors.otp)}
                                helperText={formik.touched.otp && formik.errors.otp}
                            />

                            <div className="flex items-center justify-between text-sm pt-1">
                                <span className="opacity-60">Didn't get it?</span>
                                <ResendOtpButton
                                    onResend={handleSendOtp}
                                    cooldown={resendTimer}
                                    resendText="Send Again"
                                    resendPrefixText="Retry in"
                                    resendSuffixText=" sec"
                                    buttonProps={{
                                        color: 'primary',
                                        variant: 'text',
                                        size: 'small',
                                    }}
                                />
                            </div>
                        </motion.div>
                    )}
                </AnimatePresence>

                {!isOtpSent ? (
                    <Button onClick={handleSendOtp} fullWidth variant="outlined" sx={{ py: '11px' }}>
                        {auth.loading ? <CircularProgress size={24} /> : 'Send OTP'}
                    </Button>
                ) : (
                    <motion.div
                        key="login-button"
                        initial={{ opacity: 0, y: 10 }}
                        animate={{ opacity: 1, y: 0 }}
                        transition={{ duration: 0.3, delay: 0.1 }}
                    >
                        <Button type="submit" fullWidth variant="contained" sx={{ py: '11px' }}>
                            Login
                        </Button>
                    </motion.div>
                )}
            </form>
        </div>
    );
};

export default LoginForm;

import { Button, Step, StepLabel, Stepper } from '@mui/material'
import { useState } from 'react';
import BecomeSellerFormStep1 from './BecomeSellerFormStep1'
import { useFormik } from 'formik'
import BecomeSellerFormStep2 from './BecomeSellerFormStep2'
import BecomeSellerFormStep3 from './BecomeSellerFormStep3'
import BecomeSellerFormStep4 from './BecomeSellerFormStep4'
import { createSeller, useAppDispatch } from '../../../State/seller/sellerSlice'
import { SellerProfileFormValues } from '../../../types/sellerProfileFormValuesType'

const steps = [
    "Tax Details & Mobile",
    "Pickup Address",
    "Bank Details",
    "Supplier Details"
]

const SellerAccountForm = () => {
    const [activeStep, setActiveStep] = useState(0)
    const dispatch = useAppDispatch()
 
    const formik = useFormik<SellerProfileFormValues>({
        initialValues: {
            mobile: "",

            GSTIN: "",

            pickupAddress: {
                street: "",
                city: "",
                state: "",
                postalCode: "",
                country: "",
            },
            
            bankDetails: {
                bankName: "",
                accountNumber: "",
                ifscCode: "",
                branch: "",
            },
            sellerName: "",
            email: "",
            businessDetails: {
                businessName: "",
                businessType: "",
                businessPhone: "",
                businessAddress: ""
            },
            password: ""
        },
        //validation schema
        onSubmit: async (values) => {
            try {
                console.log("Submitting seller account", values);
                const res = await dispatch(createSeller(values)).unwrap();
                console.log("Seller registered", res)
                // calling dispatch to create seller
                // await dispatch (createSeller)
                alert("Seller Account created successfully!")
            } catch (err) {
                console.error("Failed to create seller", err)
                alert("Failed to create seller account.")
            }
        }
    })

    // Move between steps or submit on final step
    const handleNext = () => {
        if (activeStep === steps.length - 1) {
            formik.handleSubmit()
        } else {
            setActiveStep(prev => prev + 1)
        }
    }

    const handleBack = () => {
        if (activeStep > 0) {
            setActiveStep(prev => prev - 1)
        }
    }

    const renderStepContent = (step: number) => {
        switch (step) {
            case 0:
                return <BecomeSellerFormStep1 formik={formik} />
            case 1:
                return <BecomeSellerFormStep2 formik={formik} />
            case 2:
                return <BecomeSellerFormStep3 formik={formik} />
            case 3:
                return <BecomeSellerFormStep4 formik={formik} />
            default:
                return null
        }
    }
    return (
        <div>
            <Stepper activeStep={activeStep} alternativeLabel>
                {steps.map((Label, index) => (
                    <Step key={Label}>
                        <StepLabel>{Label}</StepLabel>
                    </Step>
                ))}
            </Stepper>
            <section className='mt-20 space-y-10' >
                <div>
                    {renderStepContent(activeStep)}
                </div>
                {/* <div>
                    {activeStep === 0 ? (<BecomeSellerFormStep1 formik={formik} />)
                        : activeStep === 1 ? (<BecomeSellerFormStep2 formik={formik} />)
                            : activeStep === 2 ? (<BecomeSellerFormStep3 formik={formik} />)
                                : (<BecomeSellerFormStep4 formik={formik} />)}
                </div> */}
                <div className='flex items-center justify-between'>
                    <Button onClick={handleBack} variant='contained' disabled={activeStep === 0}>
                        Back
                    </Button>
                    <Button onClick={handleNext} variant='contained' >
                        {activeStep === steps.length - 1 ? "Create Account" : "Continue"}
                    </Button>
                </div>
            </section>

        </div>
    )
}

export default SellerAccountForm

import { useState, useEffect } from 'react';
import { Button, TextField, InputAdornment, CircularProgress } from "@mui/material";
import { useFormik } from "formik";
import { useAppDispatch } from "../../../State/store";
import { sellerLogin } from "../../../State/seller/sellerAuthSlice";
import { sendLoginSignupOtp } from "../../../State/authSlice";
import { toast } from "react-toastify";
import { useNavigate } from "react-router-dom";
import * as Yup from "yup";
import { motion, AnimatePresence } from "framer-motion";
import { CheckCircle } from "lucide-react";
import ResendOtpButton from "../../../component/common/ResendOtpButton";

// ✅ Validation schemas
const emailSchema = Yup.object({
    email: Yup.string().email("Invalid email").required("Email is required"),
});

const loginSchema = Yup.object({
    email: Yup.string().email("Invalid email").required("Email is required"),
    otp: Yup.string().required("OTP is required"),
});

const SellerLoginForm = () => {
    const dispatch = useAppDispatch();
    const navigate = useNavigate();
    const [isOtpSent, setIsOtpSent] = useState(false);
    const [resendTimer, setResendTimer] = useState(0);
    const [loading, setLoading] = useState(false);

    const formik = useFormik({
        initialValues: {
            email: "",
            otp: "",
        },
        validationSchema: isOtpSent ? loginSchema : emailSchema,
        onSubmit: async (values) => {
            try {
                const result = await dispatch(sellerLogin(values)).unwrap();
                toast.success("Logged in successfully!");
                navigate("/seller/dashboard");
            } catch (error: any) {
                console.error("Login failed:", error);
                toast.error(
                    typeof error === "string" ? error : error.message || "Login failed."
                );
            }
        },
    });

    const handleSendOtp = async () => {
        setLoading(true);
        try {
            await emailSchema.validate({ email: formik.values.email });
            await dispatch(sendLoginSignupOtp({
                email: formik.values.email,

            })).unwrap();
            toast.success("OTP sent to your email!");
            setIsOtpSent(true);
            setResendTimer(30);
        } catch (error: any) {
            if (error.name === "ValidationError") {
                formik.setFieldError("email", error.message);
            } else {
                toast.error("Failed to send OTP.");
            }
        } finally {
            setLoading(false);
        }
    };

    // Countdown effect
    useEffect(() => {
        let timer: NodeJS.Timeout;
        if (resendTimer > 0) {
            timer = setTimeout(() => setResendTimer((prev) => prev - 1), 1000);
        }
        return () => clearTimeout(timer);
    }, [resendTimer]);

    return (
        <div className="max-w-sm mx-auto p-6 space-y-6 border rounded shadow">
            <h1 className="text-center font-bold text-2xl text-primary-color pb-4">
                Seller Login
            </h1>

            <form onSubmit={formik.handleSubmit} className="space-y-5">
                <TextField
                    fullWidth
                    name="email"
                    label="Email"
                    value={formik.values.email}
                    onChange={formik.handleChange}
                    onBlur={formik.handleBlur}
                    error={formik.touched.email && Boolean(formik.errors.email)}
                    helperText={formik.touched.email && formik.errors.email}
                    InputProps={{
                        endAdornment: (
                            <InputAdornment position="end">
                                <AnimatePresence>
                                    {isOtpSent && (
                                        <motion.div
                                            key="success-icon"
                                            initial={{ scale: 0, opacity: 0 }}
                                            animate={{ scale: 1, opacity: 1 }}
                                            exit={{ scale: 0, opacity: 0 }}
                                            transition={{ type: "spring", stiffness: 300, damping: 15 }}
                                        >
                                            <CheckCircle className="text-green-500" size={22} />
                                        </motion.div>
                                    )}
                                </AnimatePresence>
                            </InputAdornment>
                        ),
                    }}
                />

                <AnimatePresence>
                    {isOtpSent && (
                        <motion.div
                            key="otp-field"
                            initial={{ opacity: 0, y: -10 }}
                            animate={{ opacity: 1, y: 0 }}
                            exit={{ opacity: 0, y: -10 }}
                            transition={{ duration: 0.3 }}
                            className="space-y-2"
                        >
                            <p className="font-medium text-sm opacity-60">
                                Enter OTP sent to your email
                            </p>
                            <TextField
                                fullWidth
                                name="otp"
                                label="OTP"
                                value={formik.values.otp}
                                onChange={formik.handleChange}
                                onBlur={formik.handleBlur}
                                error={formik.touched.otp && Boolean(formik.errors.otp)}
                                helperText={formik.touched.otp && formik.errors.otp}
                            />

                            {/* Resend OTP button */}
                            <div className="flex items-center justify-between text-sm pt-1">
                                <span className="opacity-60">Didn't get it?</span>
                                <ResendOtpButton
                                    onResend={handleSendOtp}
                                    cooldown={60}
                                    resendText="Send Again"
                                    resendPrefixText="Retry in"
                                    resendSuffixText=" sec"
                                    buttonProps={{
                                        color: "primary",
                                        variant: "text",
                                        size: "small",
                                    }}
                                />

                            </div>
                        </motion.div>
                    )}
                </AnimatePresence>

                {!isOtpSent ? (
                    <Button
                        onClick={handleSendOtp}
                        fullWidth
                        variant="outlined"
                        sx={{ py: "11px" }}
                        disabled={loading}
                    >
                        {loading ? ( // 👈 show spinner while loading
                            <CircularProgress size={22} />
                        ) : (
                            "Send OTP"
                        )}
                    </Button>
                ) : (
                    <motion.div
                        key="login-button"
                        initial={{ opacity: 0, y: 10 }}
                        animate={{ opacity: 1, y: 0 }}
                        transition={{ duration: 0.3, delay: 0.1 }}
                    >
                        <Button
                            type="submit"
                            fullWidth
                            variant="contained"
                            sx={{ py: "11px" }}
                        >
                            Login
                        </Button>
                    </motion.div>
                )}
            </form>
        </div>
    );
};

export default SellerLoginForm;

import { useAppSelector } from '../../../../State/store'
import Slider from 'react-slick'
import ElectricCategoryCard2 from './ElectricCategoryCard2'
import FlashHour from '../ShopByCategory/FlashHour'


const ElectricCategory = () => {
  const { customer } = useAppSelector(store => store)

  const settings = {
    dots: false,
    infinite: true,
    speed: 500,
    slidesToShow: 2,
    slidesToScroll: 1,
    autoplay: true,
    autoplaySpeed: 3000,
    arrows: false,
    centerMode: false,
    responsive: [
      {
        breakpoint: 1024,
        settings: {
          slidesToShow: 1,
        },
      },
    ],
  }

  const items = customer.homePageData?.electricCategories || []

   // ✅ show loading state while data is being fetched
    if (!customer.homePageData) {
        return (
            <div className="py-8 text-center text-gray-400">
                Loading...
            </div>
        )
    }

  if (items.length < 3) {
    return null // must have at least 3 to render properly
  }

  const firstCard = items[0]
  const middleCards = items.slice(1, items.length - 1)
  const lastCard = items[items.length - 1]

  return (
    <div className="flex items-stretch gap-1 overflow-hidden py-2 px-2">
      {/* Left static card */}
      <div className="w-[400px]">
        <FlashHour item={firstCard} />
      </div>

      {/* Middle slider */}
      <div className="flex-1 overflow-hidden">
        <Slider {...settings}>
          {middleCards.map((item, index) => (
            <div key={index} className="px-2 h-full">
              <ElectricCategoryCard2 item={item} />
            </div>
          ))}
        </Slider>
      </div>

      {/* Right static card */}
      <div className="w-[400px]">
        {/* <ElectricCategoryCard2 item={lastCard} /> */}
        
      </div>
    </div>
  )
}

export default ElectricCategory


