import { useEffect, useState } from 'react';
import FilterSection from './FilterSection'
import ProductCard from './ProductCard'
import {
    Box, Divider, FormControl, IconButton,
    InputLabel, MenuItem, Pagination,
    Select, useMediaQuery, useTheme
} from '@mui/material'
import { FilterAlt } from '@mui/icons-material'
import { useAppDispatch, useAppSelector } from '../../../State/store'
import { fetchAllProducts } from '../../../State/customer/ProductSlice'
import { useParams, useSearchParams } from 'react-router-dom'
import AsyncStateWrapper from '../../../component/AsyncStateWrapper'
import ErrorBoundary from '../../../component/ErrorBoundary'


// ✅ type-safe sort options — prevents typos and out-of-range MUI values
type SortOption = "" | "price_low" | "price_high" | "discount" | "newest"

const SORT_OPTIONS: { value: SortOption; label: string }[] = [
    { value: "",           label: "Default"          },
    { value: "price_low",  label: "Price: Low - High" },
    { value: "price_high", label: "Price: High - Low" },
    { value: "discount",   label: "Biggest Discount"  },
    { value: "newest",     label: "Newest First"      },
]

const Product = () => {
    const theme = useTheme()
    const isLarge = useMediaQuery(theme.breakpoints.up("lg"))

    // ✅ initialized as "" — matches MUI Select default option, eliminates undefined warning
    const [sort, setSort] = useState<SortOption>("")
    const [page, setPage] = useState(1)

    const dispatch = useAppDispatch()
    const [searchParams] = useSearchParams()
    const { category } = useParams()
    const { product: productState } = useAppSelector(store => store)

    const handleSortChange = (event: any) => {
        setSort(event.target.value as SortOption)
        setPage(1) // ✅ reset to page 1 when sort changes
    }

    const handlePageChange = (_: any, value: number) => {
        setPage(value)
    }

    const loadProducts = () => {
        const priceParam = searchParams.get('price')
        let minPrice: number | undefined
        let maxPrice: number | undefined

        if (priceParam) {
            const [minStr, maxStr] = priceParam.split('.')
            const minNum = Number(minStr)
            const maxNum = Number(maxStr)
            if (!isNaN(minNum)) minPrice = minNum
            if (!isNaN(maxNum)) maxPrice = maxNum
        }

        const color = searchParams.get('color') || ''
        const minDiscountParam = searchParams.get('discount')
        const minDiscount = minDiscountParam ? Number(minDiscountParam) : undefined
        const pageNumber = page - 1

        const newFilter: any = {
            category,
            color,
            pageNumber,
            sort: sort || undefined  // ✅ don't send empty string to backend
        }

        if (minPrice !== undefined) newFilter.minPrice = minPrice
        if (maxPrice !== undefined) newFilter.maxPrice = maxPrice
        if (minDiscount !== undefined) newFilter.minDiscount = minDiscount

        dispatch(fetchAllProducts(newFilter))
    }

    useEffect(() => {
        loadProducts()
    }, [dispatch, searchParams, page, category, sort])

    return (
        <div className='-z-10 mt-10'>
            <div>
                <h1 className='text-3xl text-center font-bold text-gray-700 pb-5 px-9 uppercase'>
                    {category
                        ? category.replace(/_/g, ' ')
                        : 'All Products'}
                </h1>
            </div>

            <div className='lg:flex'>
                {/* Filter Sidebar */}
                <section className='filter_section hidden lg:block w-[20%]'>
                    <FilterSection />
                </section>

                <div className='w-full lg:w-[80%] space-y-5'>
                    {/* Sort & Mobile Filter Bar */}
                    <div className='flex justify-between items-center px-9 h-[40px]'>
                        <div className='relative w-[50%]'>
                            {!isLarge && (
                                <IconButton>
                                    <FilterAlt />
                                </IconButton>
                            )}
                            {!isLarge && (
                                <Box>
                                    <FilterSection />
                                </Box>
                            )}
                        </div>

                        {/* ✅ type-safe sort select — no more MUI undefined warning */}
                        <FormControl size='small' sx={{ width: "200px" }}>
                            <InputLabel id="sort-label">Sort</InputLabel>
                            <Select
                                labelId="sort-label"
                                value={sort}
                                label="Sort"
                                onChange={handleSortChange}
                                displayEmpty
                            >
                                {SORT_OPTIONS.map(option => (
                                    <MenuItem key={option.value} value={option.value}>
                                        {option.label}
                                    </MenuItem>
                                ))}
                            </Select>
                        </FormControl>
                    </div>

                    <Divider />

                    {/* ── Product Grid ── */}
                    <ErrorBoundary>
                        <AsyncStateWrapper
                            loading={productState.loading}
                            error={productState.error}
                            empty={
                                !productState.loading &&
                                !productState.error &&
                                productState.products.length === 0
                            }
                            onRetry={loadProducts}
                            emptyMessage={
                                category
                                    ? `No products found in "${category.replace(/_/g, ' ')}".`
                                    : "No products found."
                            }
                        >
                            <section className='product_section grid sm:grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-y-5 px-5 justify-center'>
                                {productState.products.map((item) => (
                                    <ProductCard key={item.id} item={item} />
                                ))}
                            </section>
                        </AsyncStateWrapper>
                    </ErrorBoundary>

                    {/* Pagination — only when products loaded */}
                    {!productState.loading &&
                     !productState.error &&
                     productState.products.length > 0 && (
                        <div className='flex justify-center py-10'>
                            <Pagination
                                onChange={handlePageChange}
                                count={productState.totalPages || 1}
                                page={page}
                                variant="outlined"
                                color='primary'
                            />
                        </div>
                    )}
                </div>
            </div>
        </div>
    )
}

export default Product

import { useEffect, useState } from 'react';
import './ProductCard.css'
import { Button } from '@mui/material'
import { Favorite, ModeComment } from '@mui/icons-material'
import { teal } from '@mui/material/colors'
import { Product } from '../../../types/productType'
import { useNavigate } from 'react-router-dom'
import { useAppDispatch } from '../../../State/store'
import { addProductToWishlist } from '../../../State/customer/wishlistSlice'



const ProductCard = ({ item }: { item: Product }) => {
    const [currentImage, setCurrentImage] = useState(0)
    const [isHovered, setIsHovered] = useState(false);
    const navigate = useNavigate()
    const dispatch = useAppDispatch();

    useEffect(() => {
        let interval: any
        if (isHovered) {
            interval = setInterval(() => {
                setCurrentImage((prevImage) => (prevImage + 1) % item.images.length);
            }, 2000);
        }
        else if (interval) {
            clearInterval(interval);
            interval = null;
        }
        return () => clearInterval(interval);

    }, [isHovered])

    const handleWishlist = (event: any) => {
        event.stopPropagation()
        item.id && dispatch(addProductToWishlist({ productId: item.id }))
    }
    return (
        <>
            <div onClick={() => navigate(`/product-details/
            ${item.category?.categoryId}
            /${item.title}/${item.id}`)}
                className='group px-4 relative'>
                <div className='card'
                    onMouseEnter={() => setIsHovered(true)}
                    onMouseLeave={() => setIsHovered(false)}
                >

                    {item.images.map((item, index) => <img
                        className='card-media object-top'

                        src={item} alt=""
                        style={{ transform: `translateX(${(index - currentImage) * 100}%)` }}
                    />)}

                    {
                        isHovered &&
                        <div className='indicator flex flex-col items-center space-y-2'>
                            <div className='flex gap-3'>
                                <Button
                                    onClick={handleWishlist}
                                    variant='contained' color='secondary'>
                                    <Favorite sx={{ color: teal[500] }} />

                                </Button>

                                <Button variant='contained' color='secondary'>
                                    <ModeComment sx={{ color: teal[500] }} />

                                </Button>

                            </div>

                        </div>
                    }
                </div>
                <div className='details pt-3 space-y-1 group-hover-effect rounded-md'>

                    <div className='name'>
                        <h1>{item.seller?.businessDetails.businessName}</h1>
                        <p>{item.title}</p>
                    </div>
                    <div className='price flex items-center gap-3'>
                        <span className='font-sans text-gray-800'>
                            ${item.sellingPrice}
                        </span>
                        <span className='thin-line-through text-gray-500'>
                            ${item.mrpPrice}
                        </span>
                        <span className='text-primary-color font-semibold'>
                            {item.discountPercent}%
                        </span>
                    </div>

                </div>

            </div>

        </>
    )
}

export default ProductCard

import React, { useEffect, useState } from "react";
import { motion } from "framer-motion";

interface CountdownTimerProps {
    targetTime: Date;
    label?: string;
    className?: string;
}

const CountdownTimer: React.FC<CountdownTimerProps> = ({ targetTime, label, className }) => {
    const calculateTimeLeft = () => {
        const difference = +targetTime - +new Date();
        let timeLeft = { days: 0, hours: 0, minutes: 0, seconds: 0 };

        if (difference > 0) {
            timeLeft = {
                days: Math.floor(difference / (1000 * 60 * 60 * 24)),
                hours: Math.floor((difference / (1000 * 60 * 60)) % 24),
                minutes: Math.floor((difference / (1000 * 60)) % 60),
                seconds: Math.floor((difference / 1000) % 60),
            };
        }
        return timeLeft;
    };

    const [timeLeft, setTimeLeft] = useState(calculateTimeLeft());

    useEffect(() => {
        const timer = setInterval(() => {
            setTimeLeft(calculateTimeLeft());
        }, 1000);
        return () => clearInterval(timer);
    }, [targetTime]);

    const isExpired = +targetTime - +new Date() <= 0;

    const formatNumber = (num: number) => String(num).padStart(2, "0");

    return (
        <div className={`flex flex-col items-center ${className}`}>
            {label && (
                <p className="text-sm font-medium text-brandWhite-color mb-1">{label}</p>
            )}

            {!isExpired ? (
                <motion.div
                    className="flex space-x-2"
                    initial={{ opacity: 0, y: 10 }}
                    animate={{ opacity: 1, y: 0 }}
                    transition={{ duration: 0.4 }}
                >
                    {["days", "hours", "minutes", "seconds"].map((unit) => (
                        <div key={unit} className="flex flex-col items-center">
                            <span className="text-lg font-bold text-white">
                                {formatNumber((timeLeft as any)[unit])}
                            </span>
                            <span className="text-xs text-white/70 capitalize">{unit}</span>
                        </div>
                    ))}
                </motion.div>
            ) : (
                <p className="text-sm text-red-500 font-semibold">Offer Ended</p>
            )}
        </div>
    );
};

export default CountdownTimer;

import { useEffect, useState } from 'react';
import { Formik, Form } from "formik";
import BasicInfoForm from "./BasicInfoForm";
import BusinessDetailsForm from "./BusinessDetailsForm";
import BankDetailsForm from "./BankDetailsForm";
import PickupAddressForm from "./PickupAddressForm";
import { profileValidationSchema } from "../../../component/validation/profileValidationSchema";
import { api } from "../../../config/Api";
import { SellerProfileFormValues } from "../../../types/sellerProfileFormValuesType";
import Card from "../../../component/common/Card"; // 👈 import the new Card component
import CardActions from "../../../component/common/CardActions";

const Profile = () => {
  const [initialValues, setInitialValues] = useState<SellerProfileFormValues | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [editingCard, setEditingCard] = useState<string | null>(null);

  const token = localStorage.getItem("jwt");

  const fetchProfile = async () => {
    try {
      const res = await api.get("/sellers/profile", {
        headers: { Authorization: `Bearer ${token}` },
      });
      setInitialValues(res.data);
    } catch (err) {
      setError("Failed to load profile.");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchProfile();
  }, []);

  const handleSubmit = async (
    values: SellerProfileFormValues,
    { setSubmitting }: { setSubmitting: (isSubmitting: boolean) => void }
  ) => {
    try {
      await api.put(`/sellers/${values.id}`, values, {
        headers: { Authorization: `Bearer ${token}` },
      });
      alert("Profile updated successfully!");
    } catch (error) {
      alert("Failed to update profile.");
    } finally {
      setSubmitting(false);
    }
  };

  if (loading) return <p>Loading profile...</p>;
  if (error) return <p>{error}</p>;

  return (
    <div className="max-w-4xl mx-auto mt-8 space-y-6">
      <h2 className="text-3xl font-bold mb-4">Edit Profile</h2>

      <Formik<SellerProfileFormValues>
        initialValues={initialValues!}
        validationSchema={profileValidationSchema}
        onSubmit={(values, actions) => handleSubmit(values, actions)}
        enableReinitialize
      >
        {({ isSubmitting, values, handleChange, setFieldValue, errors, touched }) => (
          <Form className="space-y-8">

            <Card title="Basic Information"
              actions={
                <CardActions
                  isEditing={editingCard === "basic"}
                  onEdit={() => setEditingCard("basic")}
                  onSave={() => setEditingCard(null)}
                />
              }
            >
              <BasicInfoForm
                values={values}
                handleChange={handleChange}
                errors={errors}
                touched={touched}
                setFieldValue={setFieldValue}
                disabled={editingCard !== "basic"}
              />
            </Card>

            <Card title="Business Details"
              actions={
                <CardActions
                  isEditing={editingCard === "business"}
                  onEdit={() => setEditingCard("business")}
                  onSave={() => setEditingCard(null)}
                />
              }
            >
              <BusinessDetailsForm
                values={values}
                handleChange={handleChange}
                errors={errors}
                setFieldValue={setFieldValue}
                touched={touched}
                disabled={editingCard !== "business"}
              />
            </Card>

            <Card title="Bank Details"
              actions={
                <CardActions
                  isEditing={editingCard === "bank"}
                  onEdit={() => setEditingCard("bank")}
                  onSave={() => setEditingCard(null)}
                />
              }
            >
              <BankDetailsForm
                values={values}
                setFieldValue={setFieldValue}
                handleChange={handleChange}
                errors={errors}
                touched={touched}
                disabled={editingCard !== "bank"}
              />
            </Card>

            <Card title="Pickup Address"
              actions={
                <CardActions
                  isEditing={editingCard === "pickup"}
                  onEdit={() => setEditingCard("pickup")}
                  onSave={() => setEditingCard(null)}
                />
              }
            >
              <PickupAddressForm
                setFieldValue={setFieldValue}
                values={values}
                handleChange={handleChange}
                errors={errors}
                touched={touched}
                disabled={editingCard !== "pickup"}
              />
            </Card>

            <button
              type="submit"
              disabled={isSubmitting}
              className={`w-full px-6 py-3 rounded text-white font-medium mt-2 transition 
                ${isSubmitting ? 'bg-blue-400 cursor-not-allowed' : 'bg-blue-600 hover:bg-blue-700'}`}
            >
              {isSubmitting ? "Updating..." : "Save All Changes"}
            </button>

          </Form>
        )}
      </Formik>
    </div>
  );
};

export default Profile;

